CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE CHECK(username=lower(username) AND length(username) BETWEEN 3 AND 30),password TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,username TEXT UNIQUE,display_name TEXT NOT NULL DEFAULT '',bio TEXT NOT NULL DEFAULT '',theme TEXT NOT NULL DEFAULT 'rose',is_public INTEGER NOT NULL DEFAULT 0,show_creations INTEGER NOT NULL DEFAULT 0,notify_notes INTEGER NOT NULL DEFAULT 1,avatar_key TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_owner ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS recovery_codes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash TEXT NOT NULL UNIQUE,created INTEGER NOT NULL,used_at INTEGER,replaced_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS recovery_active ON recovery_codes(user_id) WHERE used_at IS NULL;
CREATE INDEX IF NOT EXISTS recovery_used ON recovery_codes(used_at) WHERE used_at IS NOT NULL;
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY,kind TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO templates(id,kind) VALUES ('letter','letter'),('heartbeat','heartbeat'),('memory','memory'),('forever','forever'),('surprise','surprise');
CREATE TABLE IF NOT EXISTS creations(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,template TEXT NOT NULL REFERENCES templates(id),draft TEXT NOT NULL,published TEXT,share TEXT UNIQUE,listed INTEGER NOT NULL DEFAULT 0,published_listed INTEGER NOT NULL DEFAULT 0,published_preview TEXT,updated INTEGER NOT NULL,created INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS creations_owner ON creations(owner,updated DESC);
CREATE TABLE IF NOT EXISTS creation_assets(id TEXT PRIMARY KEY,creation_id TEXT NOT NULL REFERENCES creations(id) ON DELETE CASCADE,object_key TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,role TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assets_creation ON creation_assets(creation_id);
CREATE UNIQUE INDEX IF NOT EXISTS asset_roles ON creation_assets(creation_id,role);
CREATE TABLE IF NOT EXISTS inboxes(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,slug TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,recipient TEXT NOT NULL REFERENCES inboxes(user_id) ON DELETE CASCADE,name TEXT,body TEXT NOT NULL,favorite INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS messages_inbox ON messages(recipient,created DESC);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,created INTEGER NOT NULL,seen INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS notifications_owner ON notifications(user_id,created DESC);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,category TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,reporter TEXT REFERENCES users(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'open',created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reports_queue ON reports(status,created DESC);
CREATE TABLE IF NOT EXISTS moderation_records(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,decision TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rate_expiry ON rate_limits(expires);
CREATE TABLE IF NOT EXISTS storage_gc(object_key TEXT PRIMARY KEY,created INTEGER NOT NULL);
